<div class="crpcrm-request-filters"><form method="get"><input type="hidden" name="page" value="crpcrm-staff"><input type="hidden" name="staff_tab" value="requests"><div class="crpcrm-filter-grid"><?php if($can_manage): ?><label>کارمند<select name="user_id"><option value="">همه</option><?php foreach($staff_users as $u): ?><option value="<?php echo esc_attr($u->ID); ?>" <?php selected($filters['user_id'] ?? '',$u->ID); ?>><?php echo esc_html($u->display_name); ?></option><?php endforeach; ?></select></label><?php endif; ?><label>دسته‌بندی<select name="category"><option value="">همه</option><?php foreach($categories as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($filters['category'] ?? '',$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label><label>اولویت<select name="priority"><option value="">همه</option><?php foreach($priorities as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($filters['priority'] ?? '',$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label><label>وضعیت<select name="status"><option value="">همه</option><?php foreach($request_statuses as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($filters['status'] ?? '',$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label></div><?php submit_button('اعمال فیلتر','secondary','',false); ?></form></div>
